UPDATE sys_report_chart SET dataset_id = #{record.datasetId}, chart_name = #{record.chartName}, chart_type = #{record.chartType},
    dimensions = #{record.dimensions}, measures = #{record.measures}, filters = #{record.filters},
    sort_config = #{record.sortConfig}, limit_rows = #{record.limitRows}, style_config = #{record.styleConfig},
    version = version + 1, update_by = #{record.updateBy}, update_time = CURRENT_TIMESTAMP
WHERE tenant_id = #{record.tenantId} AND chart_id = #{record.chartId} AND owner_id = #{record.ownerId}
    AND deleted = 0 AND version = #{expectedVersion}
